import {showLayerMove} from './layer-move.js';
import {canMoveLayerSequence} from '../animation/layer-move.js';
import {commandIcon} from './command-icons.js';
import {layerBlocks,splitBlock,copyBlock,pasteBlock} from '../animation/blocks.js';
import {audioClips,splitAudio} from '../audio/clips.js';
import {find,isLocked,clone} from '../document/model.js';
import {escape} from '../renderer/svg.js';
export const sequenceFrame=(t,time)=>Math.max(0,Math.min(t.a.doc.duration,Math.round(time*t.a.doc.fps)/t.a.doc.fps));
function selected(t,selection){if(!selection)return null;const p=t.a.doc;if(selection.object==='audio'){const c=audioClips(p.audio).find(c=>c.id===selection.id);return c?{audio:true,b:{...c,start:c.offset,end:c.offset+c.trimEnd-c.trimStart}}:null;}const n=find(p,selection.object),b=n&&layerBlocks(n,p).find(b=>b.id===selection.id);return b?{n,b,audio:false}:null;}
export function cutSequenceBlock(t,selection,time){const s=selected(t,selection),cut=sequenceFrame(t,time);if(!s)return false;if(s.n&&isLocked(t.a.doc,s.n.id)){t.a.toast('Unlock this layer before cutting.');return false;}if(!Number.isFinite(cut)||cut<=s.b.start+1e-7||cut>=s.b.end-1e-7){t.a.toast('Tap inside a block, leaving time on both sides.');return false;}t.a.mutate('Razor sequence block',()=>{const id=s.audio?splitAudio(t.a.doc.audio,s.b.id,cut):splitBlock(s.n,t.a.doc,s.b.id,cut);t.blockSelection={object:selection.object,id};});t.a.toast('Cut at frame '+Math.round(cut*t.a.doc.fps));return true;}
export function copySequenceBlock(t,selection=t.blockSelection){const s=selected(t,selection);if(!s||s.b.kind==='reference')return false;t.blockClipboard=s.audio?{audio:true,clip:clone(s.b),duration:s.b.end-s.b.start,assetId:t.a.doc.audio.assetId}:copyBlock(s.n,t.a.doc,s.b.id);t.blockControls();t.a.toast('Block copied.');return true;}
export function pasteSequenceBlock(t,time=t.a.time){const a=t.a,data=t.blockClipboard;if(!data)return false;const start=sequenceFrame(t,time);a.mutate('Paste sequence block',()=>{if(data.audio){if(a.doc.audio?.assetId!==data.assetId)throw Error('This copied recording belongs to another audio asset.');const end=start+data.duration;if(end>600)throw Error('Paste would exceed 10 minutes.');const clip={...clone(data.clip),id:crypto.randomUUID(),offset:start};delete clip.start;delete clip.end;a.doc.audio.clips=[...audioClips(a.doc.audio),clip];a.doc.duration=Math.max(a.doc.duration,end);t.blockSelection={object:'audio',id:clip.id};}else t.blockSelection={object:data.object,id:pasteBlock(a.doc,data,start)};});return true;}
export function setSequenceGesture(t,mode){if(t.g){syncRazor(t);t.a.toast('Finish the current timeline gesture first.');return;}t.touchMode=['select','scrub','razor'].includes(mode)?mode:'select';t.lastBlockTap=null;syncRazor(t);t.a.toast(t.touchMode==='razor'?'Razor: tap a block to cut · hold for Copy/Paste':t.touchMode==='scrub'?'Scrub time · hold a block for Copy/Paste':'Select / move blocks · hold for Copy/Paste');}
export function syncRazor(t){const button=document.querySelector('#timeline-razor'),select=document.querySelector('#timeline-touch-mode');if(button){button.setAttribute('aria-pressed',t.touchMode==='razor');button.classList.toggle('active',t.touchMode==='razor');}if(select)select.value=t.touchMode;t.scroll?.classList?.toggle('razor-mode',t.touchMode==='razor');}
export function bindTimelineRazor(t){const select=document.querySelector('#timeline-touch-mode'),toolbar=document.querySelector('.block-toolbar');if(select&&!select.querySelector('option[value="razor"]')){const o=document.createElement('option');o.value='razor';o.textContent='Razor / tap to cut';select.append(o);}if(toolbar&&!document.querySelector('#timeline-razor')){const b=document.createElement('button');b.id='timeline-razor';b.type='button';b.title='Razor: tap a sequence block to cut at that frame. Hold for Copy/Paste.';b.setAttribute('aria-pressed','false');b.innerHTML=commandIcon('razor')+'<span>Razor</span>';b.onclick=()=>setSequenceGesture(t,t.touchMode==='razor'?'select':'razor');toolbar.querySelector('#block-options')?.after(b);}if(select)select.onchange=e=>setSequenceGesture(t,e.target.value);t.scroll.addEventListener?.('contextmenu',e=>{const lane=e.target.closest('.track-lane');if(!lane||t.g?.edit)return;e.preventDefault();clearSequenceHold(t);t.a.properties.flush();t.a.pause();const hit=e.target.closest('[data-block]'),selection=hit?{object:hit.dataset.blockObject||'audio',id:hit.dataset.block}:null;showSequenceClipboard(t,e,selection,laneScope(lane),sequenceFrame(t,t.time(e)));});document.addEventListener?.('visibilitychange',()=>{if(!document.hidden)return;clearSequenceHold(t);if(t.g?.edit)t.a.history.cancel();t.g=null;t.pointers?.clear();});syncRazor(t);}
export function clearSequenceHold(t){if(t.sequenceHoldTimer!==undefined)clearTimeout(t.sequenceHoldTimer);t.sequenceHoldTimer=undefined;}
export function laneScope(lane){return lane.closest('[data-layer]')?.dataset.layer||(lane.closest('.audio-row')?'audio':null);}
export function startSequenceHold(t,e,selection,lane){clearSequenceHold(t);if(!['touch','mouse','pen'].includes(e.pointerType)||lane.closest('.ruler'))return;const g=t.g;g.holdOrigin={x:e.clientX,y:e.clientY};const scope=selection?.object||laneScope(lane),time=sequenceFrame(t,t.time(e));if(!scope)return;t.sequenceHoldTimer=setTimeout(()=>{clearSequenceHold(t);if(t.g!==g||g.moved||g.holdMoved||t.pointers.size!==1)return;t.g=null;t.lastBlockTap=null;for(const id of t.pointers.keys())if(t.scroll.hasPointerCapture?.(id))t.scroll.releasePointerCapture(id);t.pointers.clear();t.owner=null;t.a.safe(()=>showSequenceClipboard(t,e,selection,scope,time));},550);}
export function showSequenceClipboard(t,e,selection,scope,time){const a=t.a,s=selected(t,selection),data=t.blockClipboard,paste=!!data&&(scope==='audio'?!!data.audio:!data.audio&&!!find(a.doc,data.object)&&!isLocked(a.doc,data.object)),copy=!!s&&s.b.kind!=='reference',source=data&&!data.audio?find(a.doc,data.object)?.name:'audio',move=scope&&scope!=='audio'?canMoveLayerSequence(a.doc,scope):false,d=a.dialog('Sequence clipboard',`<p class="subtle">Frame ${Math.round(time*a.doc.fps)} · ${s?escape(s.b.name):'empty lane'}</p><div class="sequence-clipboard-actions"><button data-sequence-copy ${copy?'':'disabled'}>Copy block</button><button data-sequence-paste ${paste?'':'disabled'}>Paste ${paste&&scope!=='audio'?'into '+escape(source||'source layer'):'block'} here</button>${scope&&scope!=='audio'?`<button data-sequence-move ${move?'':'disabled'}>Move layer sequence…</button>`:''}</div><p class="subtle">Paste starts at this frame. The playhead stays where it is.</p>`,{modal:false});d.classList.add('sequence-clipboard-menu');const vw=globalThis.innerWidth||1024,vh=globalThis.innerHeight||768;d.style.left=Math.max(8,Math.min(vw-328,e.clientX))+'px';d.style.top=Math.max(8,Math.min(vh-220,e.clientY-90))+'px';const mover=d.querySelector('[data-sequence-move]');if(mover)mover.onclick=()=>a.safe(()=>{if(move){d.close();showLayerMove(a,scope);}});d.querySelector('[data-sequence-copy]').onclick=()=>a.safe(()=>{if(copy)copySequenceBlock(t,selection);d.close();});d.querySelector('[data-sequence-paste]').onclick=()=>a.safe(()=>{if(paste)pasteSequenceBlock(t,time);d.close();});return d;}
